import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"Dropbox 模块","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/modules/dropbox.md","filePath":"zh-Hans/deep-dive/modules/dropbox.md","lastUpdated":1795853957000}`),a={name:`zh-Hans/deep-dive/modules/dropbox.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="dropbox-模块" tabindex="-1">Dropbox 模块 <a class="header-anchor" href="#dropbox-模块" aria-label="Permalink to “Dropbox 模块”">​</a></h1><p>Dropbox 模块注册 <code>dropbox</code> 远端文件系统。它把仓库存储在一个 Dropbox 应用的应用文件夹内，通过 Dropbox 公开 API 执行文件操作。模块使用带 PKCE 的 Dropbox OAuth 2.0 认证，不使用第三方服务器或代理。</p><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to “设置”">​</a></h2><p>模块添加一个 <strong>Dropbox</strong> 设置分组。在选择 Dropbox 作为远端文件系统之前，先配置这些设置：</p><h3 id="连接账户-账户已连接" tabindex="-1">连接账户 / 账户已连接 <a class="header-anchor" href="#连接账户-账户已连接" aria-label="Permalink to “连接账户 / 账户已连接”">​</a></h3><p>这个设置发起 Dropbox 授权流程。授权后，模块把刷新令牌安全地存入 Obsidian 的密钥存储，并按需用它换取短期访问令牌。<strong>Disconnect</strong> 选项向 Dropbox 撤销该令牌组、把它从密钥存储移除、清除所有缓存的访问令牌，并删除存储的账户标识。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>连接 Dropbox 账户会在 <strong>Obsidian 钥匙串中创建一个名为 <code>sync-engine-dropbox-refresh-token</code> 的新密钥</strong>。这个密钥完全由 Sync Engine 管理，用作换取 Dropbox 访问令牌的刷新令牌。请勿将它用于其他用途。</p></div><h3 id="基目录" tabindex="-1">基目录 <a class="header-anchor" href="#基目录" aria-label="Permalink to “基目录”">​</a></h3><p>这定义 Dropbox 应用文件夹内作为该仓库根目录的文件夹。该值按目录路径规范化。留空时保持为 <code>/</code>，即应用文件夹的根。指定的文件夹在第一次同步时自动创建。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>基目录位于应用文件夹内，这是一个由应用管理的命名空间（在 Dropbox 网页界面显示为 <code>Applications/&lt;应用名&gt;</code>）。模块只能看到并操作自己应用文件夹内的文件。应用文件夹之外的文件或文件夹对这个模块不可见。</p></div><h3 id="删除到垃圾桶" tabindex="-1">删除到垃圾桶 <a class="header-anchor" href="#删除到垃圾桶" aria-label="Permalink to “删除到垃圾桶”">​</a></h3><p>启用时，远端删除的文件被移入 Dropbox 垃圾桶而不是永久移除。禁用时，被删除的文件立即永久清除。注意 Dropbox 通常在 30 天后清空垃圾桶中的条目。</p><h2 id="认证流程" tabindex="-1">认证流程 <a class="header-anchor" href="#认证流程" aria-label="Permalink to “认证流程”">​</a></h2><p>模块使用带 PKCE (S256) 和自定义 <code>obsidian://</code> 重定向的 OAuth 2.0 授权码流程，Dropbox 在桌面和移动端都支持它：</p><ol><li>点击 <strong>Connect</strong> 时，模块生成一个 code verifier 及其 S256 challenge，外加一个随机 state 值，然后显示一个带 <strong>Open Dropbox</strong> 按钮的对话框。</li><li>该按钮在系统浏览器中打开 Dropbox 的授权页面。页面请求离线访问，外加下面列出的全部 scope。在那里批准访问。</li><li>Dropbox 重定向到 <code>obsidian://sync-engine-dropbox-auth?code=...&amp;state=...</code>，重新打开 Obsidian 并把回调交给模块。模块验证 <code>state</code> 值与待处理请求一致，然后携带 PKCE verifier 在 Dropbox 的令牌端点交换授权码。</li><li>Dropbox 返回短期访问令牌、刷新令牌和账户 id。模块把刷新令牌存入 Obsidian 的密钥存储，并把访问令牌缓存在内存中。</li><li>之后的 Dropbox 请求使用缓存的访问令牌。接近过期时，模块用刷新令牌换取新的访问令牌。HTTP 401 的失败请求会触发一次强制刷新并重试。</li></ol><p>任何环节都不涉及 client secret：PKCE 取代了它，这是 Obsidian 这类公共客户端的推荐模式。<code>state</code> 值防范过期或不匹配的回调，因此来自其他仓库窗口的残留重定向会被忽略。</p><h2 id="权限与范围" tabindex="-1">权限与范围 <a class="header-anchor" href="#权限与范围" aria-label="Permalink to “权限与范围”">​</a></h2><p>模块的 Dropbox 应用使用 <strong>App folder</strong> 权限类型，只请求这几个 OAuth scope：</p><h3 id="files-metadata-read" tabindex="-1"><code>files.metadata.read</code> <a class="header-anchor" href="#files-metadata-read" aria-label="Permalink to “files.metadata.read”">​</a></h3><p>让模块列出自己的文件并读取元数据，以发现远端变更、检查连接和解析路径。</p><h3 id="files-content-read" tabindex="-1"><code>files.content.read</code> <a class="header-anchor" href="#files-content-read" aria-label="Permalink to “files.content.read”">​</a></h3><p>让模块从自己的应用文件夹下载文件内容。</p><h3 id="files-content-write" tabindex="-1"><code>files.content.write</code> <a class="header-anchor" href="#files-content-write" aria-label="Permalink to “files.content.write”">​</a></h3><p>让模块上传文件内容、创建文件夹，并在自己的应用文件夹内删除、移动或重命名文件。</p><p><strong>App folder</strong> 权限是刻意的最小权限选择：模块只能管理它在自己应用文件夹内创建的数据。你的 Dropbox 其余部分，包括你共享或存储在应用文件夹之外的文件，对模块永远不可见，模块也没有账户级访问权限。</p><h2 id="文件元数据" tabindex="-1">文件元数据 <a class="header-anchor" href="#文件元数据" aria-label="Permalink to “文件元数据”">​</a></h2><p>Dropbox 对应用文件夹类应用没有自定义键值元数据（文件属性 API 明确排除它们），因此模块存储 API 本身携带的信息：</p><ul><li>文件修改时间通过上传时的 <code>client_modified</code> 保留，并通过 <code>stat()</code> 和 <code>list()</code> 读回。API 以秒精度存储时间戳。</li><li>文件创建时间和所有文件夹时间戳不被 Dropbox API 保留；文件还原到设备时会回退为本地创建的时间。</li><li>文件身份使用 Dropbox 的 <code>content_hash</code>，即 API 返回的由内容派生的哈希。</li></ul><h3 id="大小写敏感性" tabindex="-1">大小写敏感性 <a class="header-anchor" href="#大小写敏感性" aria-label="Permalink to “大小写敏感性”">​</a></h3><p>Dropbox 路径不区分大小写，但保留大小写。仅大小写不同的两个本地文件无法在应用文件夹中共存；模块无法在远端把它们区分开，因此该后端不支持包含仅大小写差异重名的仓库。仅大小写的重命名通过一个临时中间名执行，因为 Dropbox 的移动端点直接拒绝它们。</p><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to “批量操作”">​</a></h2><p>模块自带一个远端优化器，为 Dropbox 替换插件的层级优化器。它保留层级语义（祖先排序、伞状归并、移动门控），并额外把符合条件的删除、移动和文件夹创建合并到对应的 Dropbox 批量端点（<code>delete_batch</code>、<code>move_batch_v2</code>、<code>create_folder_batch</code>），而不是每个文件发一个请求。Dropbox 异步应答的批量任务会被轮询直到完成，逐条目的失败只 reject 它所属的任务。会在同一次批量调用内冲突的移动，以及仅大小写的重命名，都单独执行。</p><p>下载和上传不批量：<code>write()</code> 用单个上传请求，<code>writeStream()</code> 用并发的上传会话（4 路并行的 4 MiB 对齐追加），下载通过对齐的 HTTP range 请求流式传输。</p><h2 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to “隐私政策”">​</a></h2><p>最后更新于 <strong>2026 年 11 月 3 日</strong>。</p><h3 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h3><p>本隐私政策说明 Obsidian 的 Sync Engine 插件与 Dropbox 模块（下称&quot;插件&quot;）在你连接 Dropbox 账户时如何处理你的数据。插件是 MIT 协议授权的开源软件。</p><h3 id="我们收集的数据" tabindex="-1">我们收集的数据 <a class="header-anchor" href="#我们收集的数据" aria-label="Permalink to “我们收集的数据”">​</a></h3><p><strong>我们不收集任何数据。</strong> 插件没有遥测、没有分析、没有远程日志服务，也没有后端服务器。任何关于你、你的文件或你的使用情况的信息都不会离开你的本地设备。</p><h3 id="你的数据如何被处理" tabindex="-1">你的数据如何被处理 <a class="header-anchor" href="#你的数据如何被处理" aria-label="Permalink to “你的数据如何被处理”">​</a></h3><p><strong>Dropbox 账户连接</strong>：</p><p>点击 &quot;Connect&quot; 时，插件直接从你的设备打开 Dropbox 的授权页面。插件只请求以下 scope，且限定于它自己的应用文件夹：</p><ul><li><code>files.metadata.read</code>：读取应用文件夹内的文件和文件夹元数据</li><li><code>files.content.read</code>：从应用文件夹下载文件内容</li><li><code>files.content.write</code>：在应用文件夹内上传、创建、移动和删除文件</li></ul><p>你的 Dropbox 其余部分对插件永远不可见。</p><p><strong>令牌存储</strong>：</p><p>OAuth 刷新令牌只存储在你本地设备的 Obsidian 加密密钥存储中。令牌从不传输给任何第三方，从不记录日志，也从不出现在崩溃报告或诊断信息中。</p><p><strong>文件操作</strong>：</p><p>所有同步操作都由你手动触发或调度。文件读写直接发生在你的本地 Obsidian 仓库与 Dropbox 之间，经 Dropbox 的 API 完成。没有任何中间服务器参与。</p><p><strong>数据保留</strong>：</p><p>你的数据只存在于你的本地设备和你的 Dropbox 账户中。点击 &quot;Disconnect&quot; 时，插件：</p><ol><li>向 Dropbox 撤销 OAuth 令牌组</li><li>从 Obsidian 密钥存储删除所有已存储的令牌</li></ol><p>断开连接后，你的设备上不会残留任何 Dropbox 账户连接的痕迹。</p><h3 id="第三方" tabindex="-1">第三方 <a class="header-anchor" href="#第三方" aria-label="Permalink to “第三方”">​</a></h3><p>涉及的唯一第三方服务是 Dropbox 的 OAuth 和文件 API，由你直接授权。除使用其公开 API 外，我们与 Dropbox 没有任何关系。我们不向任何实体共享、出售或转移任何数据。</p><h3 id="你的权利" tabindex="-1">你的权利 <a class="header-anchor" href="#你的权利" aria-label="Permalink to “你的权利”">​</a></h3><p>你拥有完全的控制：</p><ul><li>所有数据都在你的本地设备上，随时可以检查</li><li>点击 &quot;Disconnect&quot; 立即清除所有本地凭据</li><li>随时在你的 Dropbox 账户的已连接应用设置中撤销访问</li><li>无论插件状态如何，你的文件都保留在你的 Dropbox 中</li></ul><h3 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to “变更”">​</a></h3><p>本政策的更新将发布在插件的 GitHub 仓库和 <code>https://sync.consensia.cc</code>。变更后的继续使用视为接受。</p><h3 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to “联系方式”">​</a></h3><p>隐私相关问题请在我们 GitHub 仓库中提交 issue。</p><h2 id="服务条款" tabindex="-1">服务条款 <a class="header-anchor" href="#服务条款" aria-label="Permalink to “服务条款”">​</a></h2><p>最后更新于 <strong>2026 年 11 月 3 日</strong>。</p><h3 id="接受条款" tabindex="-1">接受条款 <a class="header-anchor" href="#接受条款" aria-label="Permalink to “接受条款”">​</a></h3><p>安装或使用 Obsidian 的 Sync Engine 插件与 Dropbox 模块（下称&quot;插件&quot;），即表示你同意这些条款。不同意请立即卸载插件。</p><h3 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to “许可”">​</a></h3><p>插件以 MIT 协议提供。你可以按该协议条款自由使用、修改和分发它。</p><h3 id="无担保" tabindex="-1">无担保 <a class="header-anchor" href="#无担保" aria-label="Permalink to “无担保”">​</a></h3><p><strong>插件按&quot;现状&quot;提供，不附带任何形式的担保，无论是明示还是暗示，包括但不限于对适销性、特定用途适用性和不侵权的担保。作者和版权持有人不对因使用插件产生的任何索赔、损害或其他责任负责，包括数据丢失、同步失败或 Dropbox API 变更。</strong></p><h3 id="用户责任" tabindex="-1">用户责任 <a class="header-anchor" href="#用户责任" aria-label="Permalink to “用户责任”">​</a></h3><p>你独自负责：</p><ul><li>维护 Dropbox 账户凭据的安全</li><li>了解你选择同步的数据</li><li>独立于插件备份重要文件</li><li>连接账户时遵守 Dropbox 的服务条款</li><li>确保本地设备的 Obsidian 密钥存储保持安全</li></ul><h3 id="可接受的使用" tabindex="-1">可接受的使用 <a class="header-anchor" href="#可接受的使用" aria-label="Permalink to “可接受的使用”">​</a></h3><p>不得使用插件：</p><ul><li>违反 Dropbox 的 API 服务条款</li><li>访问你不拥有或未获授权的账户</li><li>规避 Dropbox 的存储或速率限制</li><li>经同步文件分发恶意软件或非法内容</li></ul><h3 id="第三方服务" tabindex="-1">第三方服务 <a class="header-anchor" href="#第三方服务" aria-label="Permalink to “第三方服务”">​</a></h3><p>插件与 Dropbox 的 OAuth 和文件 API 交互。这些服务受 Dropbox 自己的服务条款和隐私政策约束。我们无法控制 Dropbox 的服务，对其可用性、变更或终止不承担责任。</p><h3 id="断开连接与终止" tabindex="-1">断开连接与终止 <a class="header-anchor" href="#断开连接与终止" aria-label="Permalink to “断开连接与终止”">​</a></h3><p>你可以随时点击插件设置中的 &quot;Disconnect&quot; 或卸载插件来终止使用。我们保留随时停止开发或分发插件的权利，恕不另行通知。</p><h3 id="责任限制" tabindex="-1">责任限制 <a class="header-anchor" href="#责任限制" aria-label="Permalink to “责任限制”">​</a></h3><p><strong>在法律允许的最大范围内，无论基于何种责任理论，作者或贡献者均不对任何间接、附带、特殊、后果性或惩罚性损害负责，包括利润损失、数据丢失或业务中断。</strong></p><h3 id="适用法律" tabindex="-1">适用法律 <a class="header-anchor" href="#适用法律" aria-label="Permalink to “适用法律”">​</a></h3><p>本插件由位于世界各地多个司法管辖区的贡献者以自愿、非商业方式开发和维护。没有单一的适用法律。</p><p>这些条款应依据国际法的一般原则和插件分发所依据的 MIT 协议来解释。</p><h3 id="变更-1" tabindex="-1">变更 <a class="header-anchor" href="#变更-1" aria-label="Permalink to “变更”">​</a></h3><p>我们可能随时更新这些条款。变更在 GitHub 仓库中发布后生效。继续使用视为接受。</p><h3 id="联系方式-1" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式-1" aria-label="Permalink to “联系方式”">​</a></h3><p>条款相关问题请在我们 GitHub 仓库中提交 issue。</p>`,88)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};